import React from "react";
import { useEffect, useState } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import appsettings from "../../appsettings.json";
import { generateUUID, compressBase64, decompressBase64 } from "../utilities/utils";
import api from "../api/Webcall";

const CstPgLodr = () => {

    const navigate = useNavigate();
    const [searchParams, setSearchParams] = useSearchParams();

    const scrid = searchParams.get("scrid");
    const stgid = searchParams.get("stgid");
    const ver = searchParams.get("ver");
    const qid = searchParams.get("qid");

    const apiendpoints = appsettings.ApiEndpoints;

    const redirect = async () => {

        let redirectURL = "";
        let frmData = {};
        frmData["scrid"] = scrid;
        frmData["stgid"] = stgid;

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Stage List", orgid: "", vendid: "0" };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};

        await api.post(apiendpoints.CstPagStg, compressBase64(data), reqHdr)
            .then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));
                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst === "SUCCESS") {
                            if (res.body) {
                                if (res.body.Stages) {
                                    redirectURL = res.body.Stages[0].StageFile
                                }
                            }
                        }
                    }
                }
            });

        if (redirectURL !== "") {

            const convID = generateUUID();
            const frmHdr = { convid: convID, tag: "Create/Open Q", orgid: "", vendid: "0" };
            const frmData = { scrid: scrid, stgid: stgid }
            let url = "mngcscrq/crtq";
            if (qid) {
                frmData["qid"] = qid;
                url = "mngcscrq/opnq";
            }

            const data = { hdr: frmHdr, body: frmData };

            await api.post(url, compressBase64(data)).then(function (response) {
                const res = JSON.parse(decompressBase64(response.data));

                console.log(res);

                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst === "SUCCESS") {
                            if (res.body) {

                                if (res.body.qdet) {
                                    
                                    let qdet = res.body.qdet;
                                    
                                    if (qdet.sev) {
                                        if (qdet.sev.Screen) {
                                            if (qdet.sev.Screen.ev) {
                                                if (qdet.sev.Screen.ev.stagemove) {
                                                    qdet["stagemovemethod"] = qdet.sev.Screen.ev.stagemove;
                                                    qdet["sev"] = null;
                                                }
                                            }
                                        }
                                    }

                                    let qsQDet = btoa(compressBase64(JSON.stringify(qdet)));
                                    navigate("/Home" + redirectURL+"?_q=" + qsQDet);

                                }
                                
                            }
                        }
                    }
                }
            });
        }
        else
        {
            navigate("/NotFoundPage");
        }
        
    }

    useEffect(() => { redirect(); }, []);

    return (<> <h4> Loading.... </h4> </>);
}

export default CstPgLodr;
